import json, sys, html as _h

BOOK = {'title': 'Eldorado', 'author': 'Edgar Allan Poe', 'genre': 'Edgar Allan Poe: Complete Poems', 'chapters': [{'n': 1, 'title': 'Complete Text', 'text': "Gaily bedight,\n   A gallant knight,\nIn sunshine and in shadow,\n   Had journeyed long,\n   Singing a song,\nIn search of Eldorado.\n\n   But he grew old—\n   This knight so bold—\nAnd o'er his heart a shadow\n   Fell as he found\n   No spot of ground\nThat looked like Eldorado.\n\n   And, as his strength\n   Failed him at length,\nHe met a pilgrim shadow—\n   'Shadow,' said he,\n   'Where can it be—\nThis land of Eldorado?'\n\n   'Over the Mountains\n   Of the Moon,\nDown the Valley of the Shadow,\n   Ride, boldly ride,'\n   The shade replied,—\n'If you seek for Eldorado!'"}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
