"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Spirits of the Dead', 'author': 'Edgar Allan Poe', 'genre': 'Edgar Allan Poe: Complete Poems', 'chapters': [{'n': 1, 'title': 'Complete Text', 'text': "Thy soul shall find itself alone\n'Mid dark thoughts of the gray tomb-stone—\nNot one, of all the crowd, to pry\nInto thine hour of secrecy.\n\nBe silent in that solitude,\n   Which is not loneliness—for then\nThe spirits of the dead who stood\n   In life before thee are again\nIn death around thee—and their will\nShall overshadow thee: be still.\n\nThe night, though clear, shall frown—\nAnd the stars shall look not down\nFrom their high thrones in the heaven,\nWith light like Hope to mortals given—\nBut their red orbs, without beam,\nTo thy weariness shall seem\nAs a burning and a fever\nWhich would cling to thee forever.\n\nNow are thoughts thou shalt not banish,\nNow are visions ne'er to vanish;\nFrom thy spirit shall they pass\nNo more—like dew-drop from the grass.\n\nThe breeze—the breath of God—is still—\nAnd the mist upon the hill,\nShadowy—shadowy—yet unbroken,\nIs a symbol and a token—\nHow it hangs upon the trees,\nA mystery of mysteries!"}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

